// ============ Merge ============
public static Letsencrypt.Config.Builder mergeConfig(Letsencrypt.Config dst, Letsencrypt.Config src) {
Letsencrypt.Config.Builder builder = dst.toBuilder();
if (dst.getLetsEncryptEmail().isEmpty()) { builder.setLetsEncryptEmail(src.getLetsEncryptEmail()); }
if (!dst.hasHttpListener() && src.hasHttpListener()) { builder.setHttpListener(src.getHttpListener()); }
if (dst.getRenewalCheckIntervalSeconds() == 0) { builder.setRenewalCheckIntervalSeconds(src.getRenewalCheckIntervalSeconds()); }
if (dst.getFqdn().isEmpty()) { builder.setFqdn(src.getFqdn()); }
return builder;
}
public static Letsencrypt.LetsEncryptState.Builder mergeLetsEncryptState(Letsencrypt.LetsEncryptState dst, Letsencrypt.LetsEncryptState src) {
Letsencrypt.LetsEncryptState.Builder builder = dst.toBuilder();
if (!dst.hasCertData() && src.hasCertData()) { builder.setCertData(src.getCertData()); }
else if (dst.hasCertData() && src.hasCertData()) { builder.setCertData(mergeLetsEncryptCertData(dst.getCertData(), src.getCertData()).build()); }
return builder;
}
public static Letsencrypt.LetsEncryptCertData.Builder mergeLetsEncryptCertData(Letsencrypt.LetsEncryptCertData dst, Letsencrypt.LetsEncryptCertData src) {
Letsencrypt.LetsEncryptCertData.Builder builder = dst.toBuilder();
if (!dst.hasTlsCert() && src.hasTlsCert()) { builder.setTlsCert(src.getTlsCert()); }
if (!dst.hasCertmagicState() && src.hasCertmagicState()) { builder.setCertmagicState(src.getCertmagicState()); }
else if (dst.hasCertmagicState() && src.hasCertmagicState()) { builder.setCertmagicState(mergeCertMagicState(dst.getCertmagicState(), src.getCertmagicState()).build()); }
if (dst.getLastRenewed() == 0) { builder.setLastRenewed(src.getLastRenewed()); }
if (dst.getFqdn().isEmpty()) { builder.setFqdn(src.getFqdn()); }
return builder;
}
public static Letsencrypt.CertMagicState.Builder mergeCertMagicState(Letsencrypt.CertMagicState dst, Letsencrypt.CertMagicState src) {
Letsencrypt.CertMagicState.Builder builder = dst.toBuilder();
if (!dst.getIsDir()) { builder.setIsDir(src.getIsDir()); }
if (dst.getValue().isEmpty()) { builder.setValue(src.getValue()); }
if (dst.getModTime() == 0) { builder.setModTime(src.getModTime()); }
if (dst.getChildrenMap().isEmpty()) { builder.putAllChildren(src.getChildrenMap()); }
else { for (String mk : src.getChildrenMap().keySet()) {
if (dst.getChildrenMap().containsKey(mk)) { builder.putChildren(mk, mergeCertMagicState(dst.getChildrenMap().get(mk), src.getChildrenMap().get(mk)).build()); }
else { builder.putChildren(mk, src.getChildrenMap().get(mk)); }
} }
return builder;
}
public static Letsencrypt.LetsencryptConfigState.Builder mergeLetsencryptConfigState(Letsencrypt.LetsencryptConfigState dst, Letsencrypt.LetsencryptConfigState src) {
Letsencrypt.LetsencryptConfigState.Builder builder = dst.toBuilder();
if (!dst.hasConfig() && src.hasConfig()) { builder.setConfig(src.getConfig()); }
else if (dst.hasConfig() && src.hasConfig()) { builder.setConfig(mergeConfig(dst.getConfig(), src.getConfig()).build()); }
return builder;
}
